INSERT INTO `pages` (`id`, `title`, `content`, `slug`, `active`) VALUES
	(1, 'Russia in Pictures', '<p>We created this website for those who are interested in the modern Russia. We want to tell you a story of this country making links between significant events of its chronicles. We add a lot of pictures to each story, so you can see every single detail with your own eyes.</p>\r\n<p>We also highlight Russia\'s rich cultural heritage, from its literature and art, to its traditions and customs. Whether you are a student, a traveler, or simply someone interested in learning more about Russia, we hope that our website provides you with valuable insights and a deeper understanding of this fascinating country.</p>', 'index', 1),
	(2, 'About', '<p style="text-align: right;"><em>&ldquo;In all the universe nothing remains permanent and unchanged but the spirit.&rdquo;&nbsp;</em></p>\r\n<p style="text-align: right;">Anton Chekhov, the Russian writer, The Seagull</p>\r\n<p>The enigmatic &ldquo;Russian soul&rdquo; is something that has been uniting this huge country for many centuries. The history of Russia includes absolutely different periods; the country has been populated with numerous nationalities; its lands have never been the same. Nevertheless there is one thing that never has changed: its unique soul. Russia went through success and losses. It shined and scrambled out of poverty. It was powerful and powerless; gave birth to genius and cruel dictators.</p>\r\n<p>Probably these are the reasons for an incessant interest to its past and present.</p>\r\n<p>We created this website for those who are interested in the modern Russia. We want to tell you a story of this country making links between significant events of its chronicles. We add a lot of pictures to each story, so you can see every single detail with your own eyes.</p>\r\n<p>This largest country in the world is 6,592,800 square miles. In the beginning of 2015 there were 146,267,288 residents in Russia. 74% of Russian population lives in the cities. In the end of the 19th century its population was 125,640,021, and only 13% people were living in towns.</p>\r\n<p>Now-a-days an official Russian capital, Moscow, and its cultural capital, Saint-Petersburg, are overflowed (there are 8,2% of Russian residents in Moscow and 3,5% in Saint-Petersburg). More than 180 nationalities are living in the country.</p>\r\n<p>Russia is a very interesting country with its unique history, incredible cultural heritage, breathtaking nature and stunning architecture. It is the only country in the world, which touches 12 seas, has the deepest lake with drinking water in it, the oldest and the largest fortress of the middle centuries (Kremlin).</p>\r\n<p>There are a lot of stereotypes about Russia and its people. For instance, it is a wide-spread opinion that the whole country is very cold, or that all Russians love vodka.</p>\r\n<p>Russians do not like to talk a lot about their job and always look for an opportunity to have fun and celebrate something. They are gloomy and do not like to smile, but despite this fact they love to spend long evenings sitting at the dinner table and discussing their life events.</p>\r\n<p>At the website we will tell you the real story of the modern Russia. Every post includes a lot of pictures, so you may see a lot of details by yourself.</p>\r\n', 'about', 1);
INSERT INTO `posts` (`id`, `title`, `description`, `content`, `source`, `slug`, `sort`, `active`) VALUES
	(1, 'Teaching Kids With Disabilities Smile', 'Being a child with disabilities in Russia is a big issue. In fact, those kids literally have no chances for a successful and full life. The Russian society gives them no credits. Only a few enthusiasts bring their lives to teach, rehabilitate, love and integrate these children into a “healthy” society.', '<p>Being a child with disabilities in Russia is a big issue. In fact, those kids literally have no chances for a successful and full life. The Russian society gives them no credits. Only a few enthusiasts bring their lives to teach, rehabilitate, love and integrate these children into a &ldquo;healthy&rdquo; society. They work for peanuts and every single day fight for the better future of their patients.</p>\r\n\r\n<p>There were more than 500,000 children with inborn disabilities in Russia in 2012; but only 600 kid&rsquo;s rehabilitation centers function for them. One of those centers is located in Blagovar place, Bashkortostan, Russia. Every day its employees teach children how to communicate, serve themselves and even smile.</p>\r\n\r\n<p>The center has helped children 4 - 18 years old since 2006. It can serve up to 15 patients at a time. Their goal is to integrate children into the society, make them more confident and independent.</p>\r\n\r\n', '<p>Pictures: <a href="http://aquatek-filips.livejournal.com/">aquatek-filips</a></p>', 'kids-with-disabilities', 24, 1),
	(2, 'Contrasts Of Bashkortostan', 'The Republic of Bashkortostan is one of the most developed and successful Russian districts. This large industrial center has its own agricultural sector, but the most important source of this region is oil. Bashkortostan has being extracting and processing more oil than any other region in the country. Its oil processing complex is one of the largest in Europe. \r\n', '<p>Bashkortostan is one of the most developed and successful districts in Russia. This large industrial center has its own agricultural sector, but the most important source of this region is oil. Bashkortostan has being extracting and processing more oil than any other Russian region.</p>\r\n\r\n<p>This Russian region provides 17% gasoline and 15% of diesel fuel for the country. Bashkortostan is very rich with minerals and crude oil. It also has a lot of other resources, such as natural gas, coal and ferrous metal ores.</p>', NULL, 'bashkortostan', 23, 1),
	(3, 'The Most Dangerous Russian Mountains', 'The Russia’s nature is amazing and various. There are great and silent deserts, beautiful forests, wide grasslands, freezing polar areas, rapid or quiet rivers and monumental mountains in the country. Brave travelers have set a lot of expeditions to conquer uninhabited Russian lands. ', '<p>The Russia&rsquo;s nature is amazing and various. There are great and silent deserts, beautiful forests, wide grasslands, freezing polar areas, rapid or quiet rivers and monumental mountains in the country. Brave travelers have set a lot of expeditions to conquer uninhabited Russian lands. Despite the extreme danger people have always been willing to see rare lands and startling landscapes.</p>\r\n\r\n<p>Mountains are very attractive for climbers, who want to reach the top of ridges. They pursue different goals. Some of them want to enjoy stunning views; others want to test their strength. But rocks are disobedient dangerous, and sometimes they kill those who want to bridal them.</p>\r\n\r\n<p>The highest Russian mountains, located in the south, took many lives of experienced and amateur climbers. These tragedies are usually caused by bad weather, health troubles, related to conditions high in the mountains, rock falls, exposures, etc. Nevertheless alpinists from all over the world are conquering those beautiful and attractive mountains again and again.</p>', NULL, 'russian-mountains', 22, 1),
	(4, 'The Russian Nuclear Shelter Bunker 42', 'The Cold War Museum Bunker 42 is a former military facility, located at the depth of 213 feet (65 meters) in the center of Moscow. Its area is 7,000 square meters, and it includes 4 crossed tunnels. This shelter was built many years ago in the event of a nuclear attack. ', '<p>The Cold War Museum Bunker 42 is a former military facility, located at the depth of 213 feet (65 meters) in the center of Moscow. Its area is 7,000 square meters, and it includes 4 crossed tunnels. This shelter was built many years ago in the event of a nuclear attack. It was constructed in 1950 at the height of the Cold War between the USSR and the USA. A Spare Long-Range Aviation Command Post (ET-42) was located here. The idea of this secret military facility came to Joseph Stalin, the Soviet leader, after the tragedies in Hiroshima and Nagasaki.</p>\r\n\r\n<p>Stalin realized that his loyal allies could become very dangerous enemies. For that reason he delivered an order to construct a network of invulnerable underground bases. The Russian military and technical staff worked under the ground all year long, 24x7. In 1960s the nuclear shelter had enough food, water and gas in it; an air recycling system was functioning. &nbsp;A radio station, а geodesic laboratory, the Central Telegraph and a secret office for Joseph Stalin were also constructed in the bunker.</p>\r\n\r\n<p>Every single day 100-600 specialists were responsible for providing communication in the secret base. More than 2,500 employees were working here. The underground was able to function independently for several months, shielding up to 5,000 people.</p>\r\n\r\n<h2>Why it was reconstructed</h2>\r\n\r\n<p>Many years later, in the end of eighties, the Soviet leader realized that there was no risk of a nuclear attack any more, and the secret Bunker was literally taken to pieces.</p>\r\n\r\n<p>In the mid-seventies due to technical problems the bunker was reconstructed. It was planned to convert it to the needs of the Central Telegraph. But in the nineties the former shelter was declassified and sold out.</p>\r\n\r\n<p>In 2006 the interactive museum of the Cold War was opened here. Visitors are allowed to try on an authentic military uniform, touch weapons, walk through secret tunnels and &ldquo;work&rdquo; as a radioman. Bunker 42 is opened 24x7, and many guests have enjoyed this place in the night.</p>\r\n\r\n<h2>The Cold War</h2>\r\n\r\n<p>The USA did not share details on its nuclear program and considered a possibility on communists attack. To prevent Russian nuclear attack, the US military planes with nuclear bombs flew around the world.</p>\r\n\r\n<p>During the war there was a weapon race between the USA and the former USSR. Soviet Union considered a building in the center of Pentagon as an extremely important object, which was used as a secret meeting-room. For that reason Russian nuclear weapons were pointed at it.</p>\r\n\r\n<p>It is hard to believe, but during the Cold War two countries discussed a possibility of exploring the space together. &nbsp;&nbsp;</p>\r\n\r\n<p>The Cold War was over in November of 1990 and the Iron Curtain finally fell.&nbsp;</p>\r\n\r\n<h2>Video</h2>\r\n\r\n<p><iframe allowfullscreen="" frameborder="0" height="480" src="https://www.youtube.com/embed/RbRKsUf2fUo?rel=0" width="853"></iframe></p>\r\n\r\n<p>&nbsp;</p>\r\n', NULL, 'bunker-42', 19, 1),
	(5, 'Ostankino Tower', 'Ostankino Tower is Moscow a television and radio tower. It was erected in 1967. The Russian constructor Nikolai Nikitin constructed this building. It is 1771 ft. (540 m) tall. This building is the tallest in Europe and 8th tallest freestanding tower in the world. \r\n', '<p>Ostankino Tower is a television and radio tower in Moscow. It was erected in 1967. The Russian constructor Nikolai Nikitin constructed this building. It is 1771 ft. (540 m) tall. This building is the tallest in Europe and 8th tallest freestanding tower in the world.</p>\r\n\r\n<p>Television came to Russia in 1938. In the very begining a broadcasting Shabolovka Tower was used as support for large antennas of TV and radio stations. It was constructed by a Russian engeneer Vladimir Grigorievich Shukhov.</p>', NULL, 'ostankino-tower', 20, 1),
	(6, '"Dead" And "Alive" Places of North Ossetia', 'The Republic of North Ossetia-Alania is located in south of Russia. This place is now a home for more than 100 nationalities. Its ecosystem is also deverse. Plains, riffs, mountains, rivers and canyons make this part of the country extremely interesting for travelers, tourists and climbers.', '<p>The Republic of North Ossetia-Alania is located in south of Russia. This place is now a home for more than 100 nationalities. Its ecosystem is also deverse. Plains, riffs, mountains, rivers and canyons make this part of the country extremely interesting for travelers, tourists and climbers.</p>\r\n\r\n<p>Silent and gorgeous mountains of this land have been a valuable treasure for many centuries. They amaze tourists, and provide the republic with valuable minerals.</p>\r\n', NULL, 'north-ossetia-places', 21, 1),
	(7, ' The Museum of Stalin\'s Repressions', 'Political repressions in the Soviet Russia affected 3,777,380 people. They were sent to prison or internally exiled in 1921-1954. Numerous Gulags (Main Administration of Camps) were constructed for those, who commuted crimes against the revolution of 1917 and communism.', '<p>Political repressions in the Soviet Russia affected 3,777,380 people. They were sent to prison or internally exiled in 1921-1954. Numerous Gulags (Main Administration of Camps), a huge network of the Soviet Union forced-labor camps (ITK), were constructed for those, who commuted crimes against the revolution of 1917 and communism. Its prisoners fought for human rights and were oppositionists to the state.</p>\r\n\r\n<h2>ITK6 or Perm-36</h2>\r\n\r\n<p>After Stalin&rsquo;s death in 1953 this Gulag was converted into a prison for those officials who were found guilty for organizing repressions. It was a harvest camp, and it had special facilities to keep prisoners in cells, which were closed 24x7.</p>\r\n\r\n<p>In December 1988 the camp was closed. Thus, Perm-36 worked for more than 4 decades.</p>\r\n\r\n<h2>The museum of the Soviet forced-labor camp</h2>\r\n\r\n<p>Later the camp was converted into a historic site and museum to preserve the dark history of repressions. It was dedicated to the history of Soviet forced labor camps and its impact on the modern Russia.</p>\r\n', NULL, 'perm-36', 18, 1),
	(8, 'Lake Baikal', 'Baikal is the lake in the southern part of Eastern Siberia in Russia. It has a tectonic origin. It is the deepest lake on the earth and the major natural reservoir of fresh water. Lake Baikal is also called the Baikal Sea.', '<p><em>Baikal is the lake in the southern part of Eastern Siberia in Russia. It has a tectonic origin. It is the deepest lake on the earth and the major natural reservoir of fresh water. Lake Baikal is also called the Baikal Sea.</em></p>\r\n', '<p>Pictures:&nbsp;<a href="http://cat-morphine.livejournal.com/60575.html">http://cat-morphine.livejournal.com/60575.html</a></p>', 'lake-baikal', 16, 1),
	(9, 'Sayano–Shushenskaya Dam', 'Sayano-Shushenskaya is the largest Russian hydroelectric plant. Its average power generation is high enough to take the 9th place among other hydroelectric power plants in the world. Built on the Yenisei River Sayano-Shushenskaya is located near Sayanogorsk city in Khakassia Region. ', '<p><em>Sayano-Shushenskaya is the largest Russian hydroelectric plant. Its average power generation is high enough to take the 9th place among other hydroelectric power plants in the world. Built on the Yenisei River Sayano-Shushenskaya is located near Sayanogorsk city in Khakassia Region. </em></p>\r\n\r\n\r\n', '<p>Pictures:&nbsp;<a href="http://cr2.livejournal.com/352740.html">http://cr2.livejournal.com/352740.html</a></p>', 'sayano-shushenskaya-dam', 17, 1),
	(10, 'Gzhel Porcelain Factory', 'Gzhel Porcelain Factory is a unique place in the Russian village of Novoharitonovo, where adorable products of national crafts are born.', '<p><em>Gzhel Porcelain Factory is a unique place in the Russian village of Novoharitonovo, where adorable products of national crafts are born.</em></p>\r\n', NULL, 'gzhel-porcelain-factory', 15, 1),
	(11, 'All-Russia Exhibition Centre', 'All-Russia Exhibition Centre or VVC (a former Exhibition of Achievements of the People\'s Economy or VDNKH) is a famous Russian trade and entertainment show. Its huge area, located in the north-east of Moscow, includes numerous exhibitions and a beautiful park. ', '<p><em>All-Russia Exhibition Centre or VVC (a former Exhibition of Achievements of the People&#39;s Economy or VDNKH) is a famous Russian trade and entertainment show. Its huge area, located in the north-east of Moscow, includes numerous exhibitions and a beautiful park.&nbsp;</em></p>\r\n\r\n', '<p>Pictures:&nbsp;<a href="http://mclaud2007.livejournal.com/14357.html">http://mclaud2007.livejournal.com/14357.html</a></p>', 'all-russia-exhibition-centre', 14, 1),
	(12, 'Moscow State University', 'Lomonosov Moscow State University is relatively young. Nevertheless it is one of the best in Russia and in the world. Have a photo tour and learn more about it.', '', '<p><a href="http://varandej.livejournal.com/266890.html">Source</a></p>', 'moscow-state-university', 9, 1),
	(13, 'Volcanoes of Kamchatka', 'The Kamchatka peninsula is a home for many beautiful volcanoes. Some of them are dormant, some are still active and dangerous. Read the photoreview to find out more.', '\r\n\r\n<p>The Kamchatka peninsula is a home for many beautiful volcanoes. Some of them are dormant, some are still active and dangerous. Read the photoreview to find out more.</p>\r\n\r\n<p><iframe height="480" src="https://www.google.com/maps/d/embed?mid=zsvi1iJBAT4E.kfqVCU5tgiqU" width="640"></iframe></p>\r\n\r\n', '<p><a href="http://lusika33.livejournal.com/22949.html">Source</a></p>', 'volcanoes-of-kamchatka', 10, 1),
	(14, 'Novodevichy Convent', 'Novodevichy Convent is one of the most beautiful places in Moscow. It was a place for believers, a prison, a shelter, a museum and a laundry. It was burned out and rebuilt. Now a days it is a UNESCO World Heritage Site.', '<p>Novodevichy Convent was founded in Moscow by Grand Prince Vasil the third in 1524. It was built in honor of the Smolensk Icon of the Mother of God. Nine years before the convent was built the prince made a vow to erect it in the event of his winning the battle for Smolensk. Therefore, in 1523, 230 kilograms of silver (507 pounds) were allocated for the monastery. The building was finished within a year, in 1525. We do not know who the foreman of this building was, Aleviz Novy or Nestor. According to the legend, Russian girls were sent to the Golden Horde by Tatar-Mongols from the land where the monastery was built. For that reason the convent was named Novodevichy, which means a new convent for girls.</p>\r\n\r\n<p><iframe allowfullscreen="" frameborder="0" height="450" src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d8988.231417577332!2d37.56387429227915!3d55.72274673038198!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0000000000000000%3A0x2aabc3ae09fd5c12!2sNovodevichy+Convent!5e0!3m2!1sen!2sus!4v1435074974405" style="border:0" width="600"></iframe></p>\r\n\r\n<p>Despite the fact that the first building of the monastery was made of wood, its towers were very high and incredibly beautiful. Elena Devochkina was the first Mother Superior of the monastery, and her grave has been attracting pilgrims for many centuries.</p>\r\n\r\n<p>Novodevichy Convent was located on the hill which led to the Moscow River, and it helped to protect the river crossing from enemies. The stone walls and 12 towers were erected later by the end of the 16th century by the example of the Kremlin.</p>\r\n\r\n<p>Despite the fact that Novodevichy has been a women&rsquo;s monastery, its impregnable walls turned it into a very safe place. In case of attack archers used it to protect the city. In 1591 the monastery&rsquo;s cannons stopped the Crimean Khan&rsquo;s warriors during their expedition against Moscow.</p>\r\n\r\n<p>In 1598 Boris Godunov accepted the throne in Cathedral of Our Lady of Smolensk in Novodevichy Convent. Moreover, many noble and wealthy women took vows in the convent and donated their property to it.</p>\r\n\r\n<p>As we have learned, the convent was a home of God, a powerful fortress, and a dark dungeon. Princess Sophia was imprisoned in the convent by the order of Peter the First in 1698-1704 after the Streltsy Uprising. Princess Evdoxia Fedorovna Lopukhina was sent to the convent after being vowed against her will.</p>\r\n\r\n<p>As Romanovs were set to the throne the monastery passed through various hands, and was burned out. Later it was rebuilt and granted with lands, jewelries and generous funding.</p>\r\n\r\n<p>New churches and church towers in baroque style were built at the territory of the convent. This massive building was initiated by the regent Sofia Alexeyevna.</p>\r\n\r\n<p>A foundling shelter which could fit up to 250 kids was opened in the convent in 1724. Girls lived there and were taught lace-making.</p>\r\n\r\n<p>Later, in the beginning of the 19th century, the Napoleon&rsquo;s army occupied the monastery and attempted to burn it out. Luckily, nuns saved it. A part of the convent&rsquo;s treasures were moved to Vologda and hidden there.</p>\r\n\r\n<p>A famous historian and restorer Pyotr Dmitrievich Baranovsky lived and worked in the monastery in 1939-1984.</p>\r\n\r\n<p>In 1943 the Moscow Theological Courses were held at the monastery. Later in 1945 Assumption Cathedral was reopened for believers. Twenty years later in 1964 the residence of the Metropolitan of Krutitsy and Kolomna Juvenalius located at the territory of Novodevichy.</p>\r\n\r\n<p>In 1992 the convent was closed and turned into the Museum of Women&#39;s Emancipation. Four years later the museum was transformed into a history and art museum. Some of its buildings were handed out. A day care, a hostel, laundries, gymnastics rooms functioned at the territory of the monastery.</p>\r\n\r\n<p>The convent has been opened for believers since 1994. Now a days it is under control of Metropolitan Krutitsy and Kolomna. The monastery owns some of its buildings, such as the Cathedral of Smolensk.</p>\r\n\r\n<p>The convent is a popular place both for believers and tourists. Many outstanding people, such as A. P. Chekhov, S. M. Soloviev, D. V. David are buried at its cemetery. The Necropolis consists of two parts. The old one was destroyed in the 20th century, and the new one was established outside the south wall.</p>\r\n\r\n<p>St. Sophia&#39;s tower is a popular place for tourists.</p>\r\n\r\n<p>Convent is a UNESCO World Heritage Site, and it is one of the most beautiful places in Moscow.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2>Video:&nbsp;The Novodevichy Сonvent in Winter</h2>\r\n\r\n<p><iframe allowfullscreen="" frameborder="0" height="360" src="https://www.youtube.com/embed/eu5FZt1O62Y?rel=0&amp;showinfo=0" width="640"></iframe></p>\r\n\r\n', '<p><a href="http://dimon-porter.livejournal.com/51276.html">Source</a></p>\r\n\r\n<p>The original text: <a href="http://www.moscow.org/moscow_encyclopedia/18_novodevichy_monastery.htm" rel="nofollow">www.moscow.org/moscow_encyclopedia/18_no<wbr />vodevichy_monastery.htm</a></p>\r\n', 'novodevichy-convent', 8, 1),
	(15, 'AvtoVAZ', 'AvtoVAZ is a Russian auto plant, one of the largest in Europe, which manufactures up to 800,000 automobiles and automobile kits yearly. This huge manufacturer with 67,000 employees was “born” on the 20th of July 1966, when the Soviet government issued a decree about building a new auto plant in Togliatti.', '<p>AvtoVAZ is a Russian auto plant, one of the largest in Europe, which manufactures up to 800,000 automobiles and automobile kits yearly. This huge manufacturer with 67,000 employees was &ldquo;born&rdquo; on the 20th of July 1966, when the Soviet government issued a decree about building a new auto plant in Togliatti.</p>\r\n\r\n<p>It was erected incredibly fast, and the first car, a legendary VAZ-2101, was manufactured here 3 years later in 1969. This car has become the symbol of the brand. Nowadays there are 6 basic car series: LADA 4х4, LADA SAMARA, LADA PRIORA, LADA GRANTA, LADA KALINA and LADA LARGUS. At the end of 2012 the factory began manufacturing the Nissan Almera as well as 2 Renault models. AvtoVAZ has organized a tour for bloggers from Tolgiatti, and here is a photo-review.</p>\r\n', '<p><a href="http://chronograph.livejournal.com/124142.html">Source</a></p>', 'avtovaz', 13, 1),
	(16, 'Icebreaker "50 Let Pobedy"', '"50 Let Pobedy" is a nuclear-powered icebreaker of project 10521. Nowadays, it is the world\'s largest icebreaker. Its construction took place at the Baltic Works in Leningrad.', '\r\n<p>This is a story of a beautiful and industrious giant icebreaker &quot;50 Let Pobedy&quot; (&quot;50 Years of Victory&quot;). We had a chance to see every single detail of the ship with our own eyes.</p>\r\n\r\n<p><img height="534" src="/files/blog/imgs/20/001.jpg" width="800" /></p>\r\n\r\n<p>The story of building of the ship is large, as well as the story of its work.</p>\r\n\r\n<p>The icebreaker is unique, and it is the largest in the world. The vessel is a modernized version of the second generation of the Arctic class icebreakers. On October 4th, 1989 the first vessel of the Arctic class was established at the Sergo Ordzhonikidze plant.</p>\r\n\r\n<p>Its constructors were planning to finish the building in the mid 90s. The ship which was ready for 73 percent was floated on the 9th of December 1993. Unfortunately, due to the lack of financing the further construction was postponed. The ship was waiting. Some of its parts got worn out and it was almost destroyed.</p>\r\n\r\n<p>In August 1995 the Russian President visited the plant, and the future vessel was renamed. But it didn&rsquo;t help to go on its construction.</p>\r\n\r\n<p>In 2003 the Russian government allocated 2,500,000,000 of rubles, and &quot;50 Let Pobedy&quot; got the second chance.</p>\r\n\r\n<p>The vessel survived the fire in 2007, and shortly after this was filled with the nuclear fuel. It completed maneuverability and speed tests. Other systems such as navigational and communication were checked carefully. The results of those tests were impressive, and the nuclear-powered icebreaker became a part of the Russian nuclear icebreaker fleet.</p>\r\n\r\n<p>On April 2nd 2007 the icebreaker made its first sail to Murmansk.</p>\r\n\r\n<p>About 300 people: the members of the ship&rsquo;s crew, the staff and other passengers are at the ship during its cruises.</p>\r\n\r\n\r\n<p>There are two nuclear reactors at the vessel with an output of 170 megawatt each. Both of them are protected from damage and are safe.</p>\r\n\r\n<p>The ship has a water desalination system which produces up to 120 tons of drinking water daily.</p>\r\n\r\n\r\n\r\n\r\n<h2>Video:&nbsp;Voyage to North Pole on Nuclear Icebreaker &#39;50 Let Pobedy&#39;</h2>\r\n\r\n<p><iframe allowfullscreen="" frameborder="0" height="480" src="https://www.youtube.com/embed/BRRy6t5K3R4?rel=0" width="853"></iframe></p>\r\n\r\n<p>&nbsp;</p>\r\n', '<p><a href="http://nikozlov.livejournal.com/51223.html">Source</a></p>', 'icebreaker-50-years-of-victory', 11, 1),
	(17, 'Peterhof', 'Peterhof is a "court of Peter", from 1944 to 1997 was renamed Peterhof. It is a major tourist, scientific and educational center to the west of St. Petersburg.', '<p>Peterhof is a city on the south coast of the Gulf of Finland, about 30 km west of St. Petersburg. It was founded in 1710 as a summer imperator&rsquo;s residence. A stunning palace and garden (Petrodvorets) are located here. In this review we will make a trip to the grotto of the Grand Cascade and the Samson Fountain, the largest triumphal monument of the first quarter of the 18th century. Then we will have a tour in its grotto that has enormous pipes and reach the Lower fountain park to find out the key secret of Peterhof Joke Fountains. Not only Peterhof is the Palace Park, but also a home town to 73,000 people. The name Peterhof stands for the German Peter&rsquo;s Court.</p>\r\n', '<p><a href="http://gavailer.livejournal.com/285982.html">Source</a></p>', 'peterhof', 12, 1),
	(18, 'Moscow Metro', 'The Moscow Metro is a heritage. Its stations are grandiose and amazing. Here are some pictures of the subway.', '<p>Let&rsquo;s face the truth. The Moscow Metro is overcrowded. And it is not as clean as the Shanghai Metro. Moreover, changing stations in the morning rush-hours looks like a sad penguin march. Nevertheless, the Moscow Metro is one of the most beautiful subways I have ever seen. So if you want to have a tour of the most adorable stations, join us!</p>\r\n\r\n<p>The first thing I would like to notice is that every station of the Moscow Metro is unique. Each station has its own history, design and architecture, as the construction started in the 30s to 50s. Architecture under Khrushchev turned to minimalism, and all stations that were built later became plain, simple and similar. Fortunately, in the 21st century everything changed and the metro got new unique stations. It is wonderful!</p>\r\n\r\n\r\n<h3>A Day of Moscow Metro</h3>\r\n\r\n<p><iframe allowfullscreen="" frameborder="0" height="480" src="https://www.youtube.com/embed/0M_5KRXykOs?rel=0&amp;showinfo=0" width="640"></iframe></p>\r\n\r\n', '<p><a href="http://lastdjedai.livejournal.com/107465.html">Source</a></p>', 'moscow-metro', 7, 1),
	(19, 'Khanty\'s Traditional Celebration', 'Deer racing, traditional Syberian clothes and meals, exciting contests. All of this is a part of an annual celebration in Khanty. Let\'s visit it!', '<p>Do you think that photofinish, mess at the start line and dramatic falls near the finish are a part of the Olimpic Games and F1 races? Not at all!</p>\r\n\r\n<p>I had a chance to see those things my own eyes at competitions during a celebration of reindeer breeder, hunter and fisherman.</p>\r\n\r\n<p>It was a soulful celebration! It was nice to find out that this celebration becomes more popular.</p>\r\n', '<p><a href="http://kukmor.livejournal.com/1003480.html">Source</a></p>', 'khantys', 4, 1),
	(20, 'Detinets, Novgorod Kremlin', 'Novgorod Kremlin, also known as Detinets, is a fortress, that was built ten centuries ago. Today this significatn Russian sight is in the list of the UNESCO World Heritage and under the Government’s protection.', '<p>Novgorod Detinets, which is also known as Novgorod Kremlin, is a citadel of Veliky Novorod. Detinets stands on the left shore of the Volkhov River and was first mentioned in 1044. Today it is in the list of the UNESCO World Heritage, which is under the Government&rsquo;s protection.</p>\r\n\r\n', '<p><a href="http://dimon-porter.livejournal.com/52031.html">Source</a></p>', 'detinets-novgorod-kremlin', 3, 1),
	(21, 'A Modern Russian Greenhouse Facility', 'Have you ever seen real tomato jungles? Let us visit a modern Russian greenhouse facility, an automated futuristic factory, and discover more facts about it.', '<p align="justify"><em>&ldquo;Oh, how many wonderful discoveries the spirit of enlightenment can give!&rdquo; </em></p>\r\n\r\n<p align="justify">A. S. Pushkin, a Russian poet.</p>\r\n\r\n', '<p><a href="http://muph.livejournal.com/403898.html">Source</a></p>', 'a-modern-russian-greenhouse-facility', 6, 1),
	(22, 'Russian Sukhoi Superjets\' Production', 'My sixth visit to Komsomolsk-na-Amure city and an aviation plant KNAAZ happened five years after my last visit here. Some years before the plant just begun to produce Super Jets, I came here every six months as a TASS agency photo correspondent.', '\r\n<p><iframe height="480" src="https://www.google.com/maps/d/embed?mid=zsvi1iJBAT4E.koeeHIReaaCc" width="640"></iframe></p>\r\n\r\n<p>My sixth visit to Komsomolsk-na-Amure city and an aviation plant KNAAZ happened five years after my last visit here. Some years before the plant just begun to produce Superjets, I came here every six months as a TASS agency photo correspondent.</p>\r\n\r\n<p>We had just one day for the tour and pictures TSOS KnAF GSS (the workshop of assembly of civil airplanes Sukhoi Superjet), and it was not enough. For that reason I have added additional pictures to my review.</p>\r\n\r\n\r\n<h2>Video:&nbsp;Sukhoi Superjet 100 Farnborough Airshow (2010)</h2>\r\n\r\n<p><iframe allowfullscreen="" frameborder="0" height="360" src="https://www.youtube.com/embed/S0xTpFydYfg?rel=0&amp;showinfo=0" width="640"></iframe></p>\r\n', '<p><a href="http://fotografersha.livejournal.com/367125.html">Source</a></p>', 'superjet', 5, 1),
	(23, 'A Walk Around St. Petersburg', 'Let’s have an ordinary walk in a surprisingly sunny St. Petersburg.', '<p>Let&rsquo;s have an ordinary walk in a surprisingly sunny St. Petersburg.</p>\r\n\r\n\r\n', '<p><a href="http://victorborisov.livejournal.com/185076.html">Source</a></p>', 'a-walk-around-st-petersburg', 2, 1),
	(24, 'Novosibirsk Museum of Railway Equipment', 'It has the largest collection of over than 100 locomotives, electrical locomotives and cars, which worked at railroads of Western Siberia. Moreover, there are Soviet passenger cars such as GAZ, Moskvich and ZAZ, trucks, tractors, and cross-country vehicles. ', '\r\n<p>Novosibirsk museum of railway equipment named after N.A.Akulinin is located in the Soviet district next to Seyatel railway station. The museum is the largest beyond the Ural region.</p>\r\n\r\n<p>It has the largest collection of over than 100 locomotives, electrical locomotives, and cars, which worked at railroads of Western Siberia. Moreover, there are Soviet passenger cars such as GAZ, Moskvich, and ZAZ, trucks, tractors and cross-country vehicles.</p>\r\n\r\n<p>It was decided to create a museum since a lot of railway machines were stored. In 1998 the head of West Siberian Railway made a decision to open the museum. After exhibits were collected, the museum was opened. It is named after Nikolay Akulinin, who has created and headed the museum.</p>\r\n\r\n<p><iframe allowfullscreen="" frameborder="0" height="480" src="https://www.youtube.com/embed/wwYXjxXFha0?rel=0" width="640"></iframe></p>\r\n\r\n<p><iframe allowfullscreen="" frameborder="0" height="480" src="https://www.youtube.com/embed/DWDdNe_zx5A?rel=0" width="640"></iframe></p>\r\n\r\n', '<p><a href="http://victorborisov.livejournal.com/185076.html">Source</a></p>', 'novosibirsk-museum-of-railway-equipment', 1, 1);
INSERT INTO `post_items` (`id`, `description`, `image`, `sort`, `post_id`) VALUES
	(1, 'There are 45 levels in the tower and many balconies. It weights 55 000 tons.', 'ostankino_tower.jpg', 1, 5),
	(2, 'Ostankino Tower\'s construction and technological infrastructure are unique. Construscors used prestressed concrete to make the tower extremely sturdy.', 'building.jpg', 2, 5),
	(3, 'Nowadays Ostankino Tower tramsmits signal for 11 TV channels, 12 radio stations and 17 satellite television programs.', 'ostankino_tower_1.jpg', 3, 5),
	(4, 'On the August 27 2000 the tower was on fire. The fire took lives of 4 people and caused disruption of TV and radio signals in Moscow area. Afterwards the tower was closed for tourists for a long period. It was reopened in 2009.', 'tower_on_fire.jpg', 4, 5),
	(5, '2 viewing platforms of Ostankino Tower are now opened for visitors. One of them is located at the altitude of 337 meters. The other - at 340 meters.', 'viewpoint.jpg', 5, 5),
	(6, 'A transparent part of the flore at the Observation Desk.', 'glass_floor.jpg', 6, 5),
	(7, 'High-speed elevators are working in the tower. Its speed is 23 feet/second (7 meter/second). They reach a height of 1138 ft. (347 meter) in 56 seconds.', 'lift.jpg', 7, 5),
	(8, 'The Ostankino Tower have been attracting tourists for many years. It is one of the most interesting sights of the Russia\'s capital.', 'ostankino_tower_2.jpg', 8, 5),
	(9, 'Sayano-Shushenskaya HPP was opened in 1978. Its total producing capacity is 6400 MW, and it is able to produce 25,500GWh during a year.', 'ssd_01.jpg', 1, 9),
	(10, 'The dam experiences water pressure of nearly 30 million tons. 60% of the pressure is neutralized by its own weight, and the rest goes to the bank.', 'ssd_14.jpg', 2, 9),
	(11, 'In May 1979 the turbine room was flooded with the spring water. As a result, the first turbine unit was completely disabled. In July 1979 it was successfully restarted.', 'ssd_03.jpg', 3, 9),
	(12, 'The plant’s official name is OJSC P. S. Neporozhny Sayano-Shushenskaya HPP, where HPP refers to hydro power plant and Neporozhny refers to Pyotr Neporozhny, the Minister of Energy & Electrification in the Soviet Union.', 'ssd_05.jpg', 4, 9),
	(13, 'The power plant serves the reservoir with total capacity of 31.34 km3, including 15.34 km3 of useful capacity.  Its area is 621 km2', 'ssd_08.jpg', 5, 9),
	(14, 'Another spring flood in 1985 destroyed 80% of the concrete spillway bottom plate. 50-millimetre anchor bolts were torned apart and carved into the bedrock at the depth of 7 meters.', 'ssd_09.jpg', 6, 9),
	(15, 'Constructors came up with idea of Sayano-Shushenskaya dam in 1960. In November 1961 geologists chose the location for the future project. Seven years layer, in 1968, the construction started.Ten years later, in 1978, it was finally opened.', 'ssd_16.jpg', 7, 9),
	(16, 'Sayano-Shushenskaya dam is the largest in Russia and the 9th in the world.', 'ssd_10.jpg', 8, 9),
	(17, 'Up to 2,000 GWh may be lost yearly after massive rainfalls because there is not enough of high-voltage transmission capacity. As a result, some water gets into turbines. In order to prevent those situations building of a new aluminum plant started in December of 2006.', 'ssd_11.jpg', 9, 9),
	(18, 'Sayano-Shushenskaya dam provides over ¼ of RusHydro generation capacity.', 'ssd_13.jpg', 10, 9),
	(19, 'The station includes the 242 meter high dam, a power plant building and an additional spillway located under the construction. The curved gravity dam\'s crest length is 1,066 meters, its width is 25 meters, base width is 105,7 meters and maximum head is 220 meters.', 'ssd_15.jpg', 11, 9),
	(20, 'Sayano-Shushenskaya HPP is constructed to be able to resist earthquakes up to 8 on the Richter magnitude scale. It is listed in the Guiness Book as the strongest dam.', 'ssd_16.jpg', 12, 9),
	(21, 'The power station is the largest station contributing to consumption in Russia’s Unified Energy Systems. Over 70% of electrical power generated by the station is consumed by four smelters of Rusal in Siberia.', 'ssd_17.jpg', 13, 9),
	(22, 'There was an accident in August of 2009, resulting in closing of the plant. Several old turbines were temporarily restarted, and others were supposed to be fully replaced with updated equipment. As of autumn 2012, 5 turbines were operating, and 3 of them were fully replaced. Full replacement was completely accomplished in 2014.', 'ssd_18.jpg', 14, 9),
	(23, 'The reliability of the HPP is often questioned in the media. The experts in hydraulic engineering constantly check station’s security structures. Sayano-Shushenskaya HPP has a valid declaration of safety.', 'ssd_19.jpg', 15, 9),
	(24, 'Baikal is located in the center of Asia, on the border of the Irkutsk region and the Republic of Buryatia. Its width ranges from 24 to 79 km, and the water surface area of Lake Baikal equals 31,722 km² (excluding islands), which is approximately equal to the area of Belgium or the Netherlands.', 'map.jpg', 1, 8),
	(25, 'Lake Baikal is the deepest lake in the world. Its maximum depth is 1,642 m. The average depth of the lake is 744.4 m. It exceeds the maximum depths of the deepest lakes on our planet.', 'kosmos.jpg', 2, 8),
	(26, 'During a freeze-up season (January 9 through May 4) Baikal is completely covered with ice, except for a small area of 20 km, which is a source of the Angara River. The period of navigation for passenger and cargo ships usually opens in June and ends in September.', 'baikal_12.jpg', 3, 8),
	(27, 'A famous Russian soft drink that looks like Coke was named after the lake was created in 1973. A special blend of herbal extracts and essential oils is the secret of the unique Baikal’s beverage taste.', 'baikal_02.jpg', 4, 8),
	(28, '65 km from Irkutsk (on the shore of Lake Baikal near the Angara River) there is a village Listvyanka - one of the most popular tourist’s destinations. The best routes start at the village and lead to the Big Cats at the peninsula Holy Nose, Olkhon Island and other places.', 'baikal_03.jpg', 5, 8),
	(29, 'Lake Baikal is a home for more than 2,600 aquatic animals (1,000 endemic species, 11 endemic families and subfamilies).', 'baikal_04.jpg', 6, 8),
	(30, 'There are many monuments of nature, culture, history and archaeology at the lake. One the most famous are North Baikal, Shaman Stone, Chivyrkuisky Gulf, Barguzinsky Bay and Ushkany Islands.', 'baikal_05.jpg', 7, 8),
	(31, 'According to the legend Baikal was the father of 336 rivers-sons and one daughter-Angara. All rivers met the father-river to replenish his waters; but his daughter fell in love with the Yenisei River and gave her father`s waters to her loved one. Therefore, the father Baikal threw a huge piece of rock (Shaman Stone) into his daughter’s body and cursed her.', 'baikal_06.jpg', 8, 8),
	(32, 'Baikal keeps about 19% (more than 23,000 km3) of the world\'s fresh water. The Great Lakes keep 22,000 km3 of fresh water.', 'baikal_07.jpg', 9, 8),
	(33, 'There are several theories about the origin of the name Baikal. It can be translated from Buryat language as "to stand" and "fire" or "to rich fire". According to a legend Lake Baikal was formed on a site of a fire-breathing mountains.', 'baikal_08.jpg', 10, 8),
	(34, 'If we will divide the lake’s water (23 615.4 cubic meters) by all Russians (141,927,300 people), then each one will get about 166,4 thousand m3 (it is about 2,773 rail tank cars of 60 tons each). According to a famous lake researcher L. Kolotilo, utilitarian value of water in the lake is $236 trillion.', 'baikal_09.jpg', 11, 8),
	(35, 'Since 1956 the lake has been used for getting hydroelectric power. Lake Baikal has become an integral part of the Irkutsk reservoir.', 'baikal_10.jpg', 12, 8),
	(36, 'Scientists believe that the lake appeared 25-35 million years ago. Since 1996 Lake Baikal is in the List of UNESCO World Heritage Sites.', 'baikal_11.jpg', 13, 8),
	(37, 'One of the main problems of preservation the Baikal natural territory flora and fauna is poaching. One of the main objects of illegal fishing is the Baikal seal.', 'baikal_01.jpg', 14, 8),
	(38, 'Many countries (Armenia, Albania or Malta) could fit on the territory of Baikal (its area is nearly 32,000 km2).', 'baikal_13.jpg', 15, 8),
	(39, 'The building of the reabilitation center\r', 'building.jpg', 1, 1),
	(40, 'Arts therapy is an important part of the treatment. \r', 'art_therapy.jpg', 2, 1),
	(41, 'Creating snowmen. \r', 'default.jpg', 3, 1),
	(42, '', '8.jpg', 4, 1),
	(43, '', 'snowmen.jpg', 5, 1),
	(44, 'The caffeteria is pretty small. Girls and boys have their lunch seperately because the room can not fit all patients at a time. \r', 'lunchtime.jpg', 6, 1),
	(45, 'Patients live in the center during their treatment. This is a girls\' bedroom. \r', 'bedroom.jpg', 7, 1),
	(46, 'Outdor and indoor activities is an important part of the therapy. \r', 'outdoor_activities.jpg', 8, 1),
	(47, '', 'reabilitation.jpg', 9, 1),
	(48, 'Its oil processing complex is one of the largest in Europe. Pictures of monumental oil processing plants in Bashkortostan are very impressive.\r', 'oil_prosessing.jpg', 1, 2),
	(49, '', 'oil_factory.jpg', 2, 2),
	(50, 'An inspiring view of Ufa city, the capital of Bashkortostan.\r', 'view_ufa.jpg', 3, 2),
	(51, 'An ambulance in Ufa city.\r', 'an_ambulance.jpg', 4, 2),
	(52, 'To see even more contrasts we have to leave the capital. A populated place Blagoar, Bashkortostan.\r', 'apartments.jpg', 5, 2),
	(53, '', 'streets.jpg', 6, 2),
	(54, 'A collective farm Zavet Lenina in Bashkortostan.\r', 'collective_farm.jpg', 7, 2),
	(55, 'A village shop in Blagovar.\r', 'store.jpg', 8, 2),
	(56, 'A typical road in Blagovar.\r', 'roads.jpg', 9, 2),
	(57, 'A bridge in Bashkortostan.\r', 'a_bridge.jpg', 10, 2),
	(58, 'The Republic of Bashkortostan is also very rich with its natural beauty. Its rivers, lakes, mountains, and parks are amazing and even monumental, just like its oil plants. The stunning nature of Bashkortostan. The Inzer River.\r', 'river_inzer.jpg', 11, 2),
	(59, 'Lake Bannoye.\r', 'bannoye_lake.jpg', 12, 2),
	(60, 'Iremel Mountain.', 'iremel_mountain.jpg', 13, 2),
	(61, 'Elbrus - a dormant volcano of the western Caucasus, is the highest mountain both in Russia and Europe. It is 18,510 feet (5,642 meters) high.', 'elbrus_2.jpg', 1, 3),
	(62, 'It has a shape of a saddle. Every year Elbrus takes lives of 15-20 climbers.', 'elbrus_3.jpg', 2, 3),
	(63, 'Experienced alpinists believe that the reason for such a big fatalities rate is light-mindless of some climbers. Sometimes people do not take mountains serious and pay for this with their lives.', 'elbrus_1.jpg', 3, 3),
	(64, 'The 2nd highest mountain in Russia and Europe is Dykh-Tau Mountain. It is 17077 ft. (5205 meters) high. It is located in Kabardino-Balkaria (south of Russia). Just one glance at the north cliff of the mountain makes you to understand that it is technically challenging.', 'dykh_tau1.jpg', 4, 3),
	(65, 'This mountain is not for dilettantes, it is for the experienced climbers. Most fatalities at this steep mountain happen due to a human-factor.', 'dykh_tau2.jpg', 5, 3),
	(66, 'The 3rd highest peak of Russia and the 4th of Europe is Koshtan-Tau Mountain. It is 16,877 ft. (5,144 meter) high.', 'koshtan_tau1.jpg', 6, 3),
	(67, 'This mountain is also in the Kabardino-Balkaria Republic. Its routes are extremely difficult, dangerous and tricky even for experienced climbers. Despite the fact that many alpinists died at this mountain, people are still interested in Kosttan-Tau\'s ice routs, rock routes and traverses.', 'koshtan_tau2.jpg', 7, 3),
	(68, 'The entrance into this military base was masked with a 19th century building. Its thick walls were covering a 20 feet (6 meters) wide silohead, labyrinths and an armored entrance to the bunker. The military complex was equipped with advanced military facilities.', 'mask.jpg', 1, 4),
	(69, 'Constructors started working on the project in 1940s. The Stalin Bunker (another shelter under the stadium "Sports and fitness company Izmaylovo", which was built in 1930th) was outdated and not safe. For more than 30 years the new bunker protected the USSR from a nuclear attack.', 'scheme.jpg', 2, 4),
	(70, 'Its new owners decided to construct a museum of the Cold War here. The underground used to have a lot of expensive furnishings and military equipment, but those items were lost. For this reason it was decided to rebuild the former base, and deliver new valuable exhibits under the ground. Nowadays the museum has original armored doors and a specific walls covering.', 'tonnel.jpg', 3, 4),
	(71, '', 'tonnel_2.jpg', 4, 4),
	(72, '', 'tonnel_4.jpg', 5, 4),
	(73, 'The Cold War (the term was invented by a writer George Orwell) started after a nuclear bomb was dropped on Hiroshima and Nagasaki in 1945. The Soviet Union and the United States were involved in it during the 2nd part of the 20th century. There were many reasons for it: the USSR did not like capitalism and was afraid on a nuclear attack. The former Soviet Union also wanted to secure its western border and spread communism worldwide.', 'poster.jpg', 6, 4),
	(74, 'Five tours of the museum: "Declassified", ZKP-42, Bunker-42, Extreme, and Soviet Russia let visitors to experience a unique atmosphere of Soviet Russia. Guests of Bunker 42 may set off a nuclear warhead, try on a military uniform, watch a movie on the Cold War period, and find out how the bunker staff operated the secret underground.', 'tryon.jpg', 7, 4),
	(75, '', 'tour.jpg', 8, 4),
	(76, 'Nowadays the museum Bunker 42 offers excursions, entertainments (such as LazerTag Strikeball, restaurant, activities for children) as well.', '11653070243_bff1b15fb7_k.jpg', 9, 4),
	(77, 'Tourists may also visit the technical sections of the shelter and see catacombs by themselves. One of the tours is devoted to an authentic atmosphere of the soviet period. A military choir sings famous old-fashioned Russian songs, such as Kalinka, Katyusha, and Smuglyanka.', '11653581926_11cdb5dc6e_k.jpg', 10, 4),
	(78, 'These mountains have also been a home for people and a crypt for departed.', 'mounts_ossetia.jpg', 1, 6),
	(79, '', 'rainbow.jpg', 2, 6),
	(80, 'An ancient fortress use to protect the region.', '2.jpg', 3, 6),
	(81, '', '3.jpg', 4, 6),
	(82, 'Two places: the City of the Dead and an ore district Sadon are located in the south of North Ossetia-Alania. The mortal village is in a settlement in Prigorodny District, Dargavs. It lies in the center of a beautiful mountain valley.', 'cod2.jpg', 5, 6),
	(83, '99 tombs and crypts of the City of the Dead were built in the 12th century by population of Dargavs for burying their loved ones.', 'cod1.jpg', 6, 6),
	(84, 'Those stone crypts were used from the 12th up to 18th centuries. Many generations used this place as a cemetery to save lands for living.', 'cod4.jpg', 7, 6),
	(85, '', 'cod3.jpg', 8, 6),
	(86, 'A populated place Verkhniy Sadon is located not far from Dargavs. It used to be an industrial center, and was built in the beginning of the 19th century around the mining industry.', 'sadon2.jpg', 9, 6),
	(87, 'This ore district was populated with miners, who worked hard to get valuable resources. In the beginning of the 20th century Caucus provided around 26-28 tons of silver-lead and zinc ores.', 'sadon1.jpg', 10, 6),
	(88, 'In 2002 this place was literally destroyed by the Sadonka River.', 'sadon3.jpg', 11, 6),
	(89, 'Its population was moved to other lands. But some people got back to Sadon to stay here.', 'sadon4.jpg', 12, 6),
	(90, 'To preserve this dark period of Russian history a museum of Stalin\'s repressions, Perm-36, was opened. Despite the fact that it is extremely important it was closed in 2014. Its directors were fired. An official from the Ministry of Culture of Perm became a new director. This replacement has totally changed the idea of this exhibition. It was said that new exhibitions may be dedicated to technical means of holding nationalists and fascists in custody.', '7.jpg', 1, 7),
	(91, 'Perm-36 (or ITK-6), a Soviet Gulag, was built in 1946 after the II World War and worked for almost 40 years as a logging camp. It was located in the north of Russia, not far from Perm city next to a populated place Kuchino. The camp was built next to the forested region near the Siberia. Earlier, in 1942, this camp was functioning at Selyanka station. This forced-labor colony\'s prisoners were responsible for logging.', '18.jpg', 2, 7),
	(92, 'This forced-labor camp had 4 barracks, that could fit up to 1,000 people. There also was a block for punishments (for those who did not want to follow the rules), headquarters building and a hospital.', '13.jpg', 3, 7),
	(93, 'Prisoners had a very strict day schedule. They woke up at 6 am, had their breakfast in a half an hour and started working after a roll-call. They worked 9 hours every day. Moreover, they had to spend 3 hours to reach to the forest in the morning and get back to their camp in the evening. Then, at 7.30 pm they had dinner and went on working inside the camp (for example, they were responsible for cleaning snow at the territory of ITK6, gardening and repairs). Prisoners went to sleep at 11 pm to wake up at 6 in the morning and go on their working hard.', '11.jpg', 4, 7),
	(94, 'Perm-36 is a mixture of an authentic camp with its original interiors and an exposition with exhibits, which were found and collected for descendants. The museum had several parts.', '12.jpg', 5, 7),
	(95, 'The first one highlighted the period of Joseph Stalin\'s repressions, described life of its prisoners and told about their crimes. The 2nd was devoted to the fight for human rights in the Soviet Union in 1960s and 1970s. The 3rd section\'s goal is to focus on educating the young visitors of the museum on the history of Gulags and totalitarianism in the Soviet Russia.', '8.jpg', 6, 7),
	(96, 'The Article 58 (it was set in 1927) of the Soviet Russia penal code, indicated enemies of workers and implied punishment for counter-revolution activists. "Traitors" and "saboteurs" could be sent to deat those, who did not report of a "counter-revolutionary activity" went to prison for 6 months. Non-reporting of a treason by a military man could coast 10 years of imprisonment. Contacts with counter-revolutionary foreigners or any help to "international bourgeoisie" was forbidden as well.', '9.jpg', 7, 7),
	(97, 'There were five periods when prisoners filled GuThe first one reffered to the collectivization period in 1929-1932. The second "wave" took place in 1934, when the Article 58 was extended. The great purge of Stalin\'s terror sent a huge amount of "enemies of workers" to camps during 1936-1938. At the peak of the repressions in 1939-1940 hundreds of thousands people from territories occupied by the Soviet Union were sent to forced-labor camps. During the II World War some prisoners were also sent to fight in penalty battalions on the front line.', '19.jpg', 8, 7),
	(98, 'Even though the number of GULAGs declined after Stalin\'s death, political repressions took place up to 80s. During 2 decades, in 60-80s, thousands were sent to prisons, mental hospitals or camps.', '5.jpg', 9, 7),
	(99, 'Gzhel potters\' faience in the 18th century had a very high quality that could rival with the creamware in England produced in the end of the 17th century.', 'gzhel_01.jpg', 1, 10),
	(100, 'The range of the factory produces more than 1,000 items of porcelain for utilitarian and decorative purposes. The most popular are tea sets, tableware, dishes, vases, decorative plates, samovars, juicers, boxes, lamps, clocks, candlesticks, chandeliers, ashtrays, souvenirs and sculptures.', 'gzhel_02.jpg', 2, 10),
	(101, 'In the beginning of the 19th century white clay was found in Gzhel. That\'s when the production of Russian domestic porcelain started. In 1810 the first porcelain factory was established by the prominent industrialist Kuznetsov.', 'gzhel_03.jpg', 3, 10),
	(102, 'In 2003 local entrepreneurs and craftsmen opened Gzhel Porcelain Factory that produced an artistic porcelain. It used traditional cobalt for painting.', 'gzhel_04.jpg', 4, 10),
	(103, 'Gzhel is a Russian-style ceramics with folk painting. It has been manufactured since 1803 in the village of Gzhel and the areas next to it.', 'gzhel_05.jpg', 5, 10),
	(104, 'Many famous artists: V. Rozanov, S. Eagle, Simonov, A. Sysoev, V. Petrov, A. Rogov, A. Kiselev, V. Sidorenko, V. Klimov cooperated with Gzhel Porcelain Factory. Nowadays the factory\'s creative team is represented with a team of 8 specialists.', 'gzhel_06.jpg', 6, 10),
	(105, 'Gzhel\'s products are made manually and well-known with its traditional Russian soul. Dynasties of experienced manufactures have being working at the factory and produced those traditional ceramic art items.', 'gzhel_07.jpg', 7, 10),
	(106, 'In the beginning of the 19th century the best artisans created Gzhel, and the production was constantly expanding. Before the war of 1812 in Gzhel there were 25 large and small factories producing porcelain.', 'gzhel_08.jpg', 8, 10),
	(107, 'Gzhel porcelain production is one of the oldest in the country. Local residents were engaged in the extraction of red clay (its deposits were very close to the surface, and it was very easy to get them).', 'gzhel_09.jpg', 9, 10),
	(108, 'The mass production of Gzhel clay started in the 17th century. In 1663 the Russian tsar Alexei Mikhailovich issued a decree "... in Gzhel parish for pharmaceutical and alchemical vessels send clay which suits to the pharmacy vessels." Numerous utilitarian spheres of clay\'s application were listed by the great Russian scientist Mikhail Lomonosov.', 'gzhel_10.jpg', 10, 10),
	(109, 'Gzhel Porcelain Factory is the largest Russian manufacturer of traditional porcelain. Over 300 hereditary craftsmen are working at the factory.', 'gzhel_11.jpg', 11, 10),
	(110, 'Gzhel is an elegant vintage, which is both decorative and utilitarian. Those items were very valuable and rare in the former Soviet Union, but it was impossible to buy them inside the country. Gzhel was available abroad for foreigners.', 'gzhel_12.jpg', 12, 10),
	(111, 'All factories in the Soviet Union were nationalized, and most of Gzhel enterprises were reorganized to produce electro porcelain. After the World War II, since 1947, the production of porcelain raised up again. Since then Gzhel got its amazing blue and white look, well- known all over the world.', 'gzhel_13.jpg', 13, 10),
	(112, 'In September 2012 Gzhel Porcelain Factory got an official Folk Art license of the XXII Olympic Winter Games in Sochi-2014 and produced a new collection with Olympic symbols which includes a beautiful set of unique mascots Sochi 2014.', 'gzhel_14.jpg', 14, 10),
	(113, 'The peak of Gzhel porcelain production took place in the 20th century. A lot of professional artists and other specialists with a degree in the field were hired with the factory. All creations during this period became the benchmark of Gzhelian art.', 'gzhel_15.jpg', 15, 10),
	(114, 'Have a look at the main building of Lomonosov Moscow State University (MSU). The north-side view is the most impressive.', '001.jpg', 1, 12),
	(115, 'This 240 meters high and 36-level university was erected in 1949-1953 by prisoners. The famous architects L. Rudnev, B. Iofan, S. Chernyshev, P. Abrosimov and V. Nasonov created the project. The rear-view', '002.jpg', 2, 12),
	(116, 'In 50s the university was the highest building in the world outside the US. This is probably one of the most outstanding masterpieces of the Russian architecture of the 20th century located in Moscow. The skyscraper belongs to the famous group of Joseph Stalin\'s 7 buildings located in the heart of Moscow. The side view', '003.jpg', 3, 12),
	(117, 'Nowadays there are a lot of modern skyscrapers in the capital, but this one will always be the magnificent part of the Moscow\'s landscape. The university is located at a 50-meters high hill not far from the Moscow River, and it seems like the building is soaring over the city. It has a charming night illumination.', '004.jpg', 4, 12),
	(118, 'Earlier the main entrance was located on the Vorobyovy Gory side.', '005.jpg', 5, 12),
	(119, 'In the 18th century the university occupied a building at Mokhovaya street in the center of Moscow, next to the Kremlin. Unfortunately the building does not exist anymore. Some blocks of MSU are still located at Mokhovaya street. The former main entrance', '006.jpg', 6, 12),
	(120, 'The triumphal columns', '007.jpg', 7, 12),
	(121, 'The sights of the main building of the university: Sculptures of architect Vera Mukhina, the author of the famous Moscow sculpture "Rabochy I Kolkhoznitsa" ("The Worker and Collective Farm Woman").', '008.jpg', 8, 12),
	(122, '', '009.jpg', 9, 12),
	(123, 'The four towers with the astronomical clock', '010.jpg', 10, 12),
	(124, '', '011.jpg', 11, 12),
	(125, 'There are faculties of Geology, Math, Geography and rectorate in the main block. The Museum of Earth Science is located in the square storey wich is decorated with the emblem.', '012.jpg', 12, 12),
	(126, 'Decoration of the level', '013.jpg', 13, 12),
	(127, '', '014.jpg', 14, 12),
	(128, 'Sculptures', '015.jpg', 15, 12),
	(129, '', '016.jpg', 16, 12),
	(130, 'The elegant Rotunda, one of the assemble halls of MSU, occupies two round levels, the 31 and 32. We will reach it a little later. Mechanical rooms are located at the 33 - 36 levels. The spire with the star is 58 meters high.', '017.jpg', 17, 12),
	(131, 'Hostels for students and postgraduates and apartments of teachers and professors.', '018.jpg', 18, 12),
	(132, 'The hostel\'s courtyard', '019.jpg', 19, 12),
	(133, '', '020.jpg', 20, 12),
	(134, '', '021.jpg', 21, 12),
	(135, 'This is a front view of the arches between the hostels and the main block.', '022.jpg', 22, 12),
	(136, 'Nowadays the main entrance is located at the south side.', '023.jpg', 23, 12),
	(137, '', '024.jpg', 24, 12),
	(138, '', '025.jpg', 25, 12),
	(139, 'The view at the top of the building', '026.jpg', 26, 12),
	(140, '', '027.jpg', 27, 12),
	(141, 'This Hall of Four Buffets is a popular place at the first floor. It has a beautiful granitic decoration.', '028.jpg', 28, 12),
	(142, 'Some more pictures of the fundamental and heavy interiors at the first level. A grandiose assemble hall and fragments of the temple of Christ the Saviour.', '029.jpg', 29, 12),
	(143, '', '030.jpg', 30, 12),
	(144, '', '031.jpg', 31, 12),
	(145, 'Those express elevators operate at certain levels and each one has its own rout.', '032.jpg', 32, 12),
	(146, 'This is the Museum of Earth Science, one of the best in Moscow. Strangers may get a tour to have a chance to visit the museum. The elevator that serves the 28th level leads to the assemble hall Rotonda.', '033.jpg', 33, 12),
	(147, '', '034.jpg', 34, 12),
	(148, 'The exit to the 31 floor at the bottom of Rotonda', '035.jpg', 35, 12),
	(149, 'The view of Rotonda', '036.jpg', 36, 12),
	(150, 'One more view at it', '037.jpg', 37, 12),
	(151, 'The dome of Rotonda', '038.jpg', 38, 12),
	(152, 'It is the 2nd largest center in the capital, which is also in the TOP-50 of largest exhibitions in the world.', '002.jpg', 1, 11),
	(153, 'The total area of ​​VVC is more than 520 hectares (the area of ​​all pavilions is 134,000 square meters).', '003.jpg', 2, 11),
	(154, 'The symbol of VVC is a huge monument The Worker and Collective Farm Woman. The sculpture was erected in 1937 for a pavilion at the Paris exhibition, cut into 65 components and placed on 28 railway platforms for transportation. The best engineers, mechanics, fitters, welders and tinsmiths set the sculpture for 11 days after transportation.', '004.jpg', 3, 11),
	(155, 'It is planned to introduce the new concept of VVC as a major cultural and exhibition center and the main Moscow public park.', '013.jpg', 4, 11),
	(156, 'The Exhibition of Achievements of the People\'s Economy was opened in 1939 and became very popular. For the first 5 months over 3,000,000 people visited it. The authors of the project had to make a decent platform filled with 250 luxurious pavilions and fountains.', '005.jpg', 5, 11),
	(157, 'One of those, the fountain Friendship of the Peoples, is surrounded with golden female sculptures. They symbolize 15 republics of the former USSR. This fountain should have been called the Golden Sheaf, which was supposed to reflect the abundance of agriculture in the USSR. However, the fountain was renamed to the Friendship of the Peoples, so that all the VDNKh pavilions looked the same. There are also many small fountains on the VVC territory, such as the Boy with a Fish, Medicine (lost in 2011), and many others.', '015.jpg', 6, 11),
	(158, 'By 1940 the exhibition was visited by 4.5 million people. When the II World War started the exhibition was closed, and all the exhibits were evacuated to Chelyabinsk.', '016.jpg', 7, 11),
	(159, 'Up to the Great October Revolution the area of the current VVC was occupied by the Township visiting circus. The circus toured the country during the summer, and returned to Moscow in the autumn.', '017.jpg', 8, 11),
	(160, 'On June 23, 1992 the President of the Russian Federation issued a decree, according to which VDNKh was renamed to the State Joint Stock Company "All-Russia Exhibition Center" (VVC). In the mid and late 1990s, many pavilions of VVC were leased by warehouses and shops.', '019.jpg', 9, 11),
	(161, 'There is a bunker located under the house of Friendship of the Peoples on VVC territory. Its capacity is 300 people, and it has everything one needs for a stand-alone 2-days accommodation. There are also a recreation room, a storage room, a room for the air filtration, and an office for the General Secretary.', '021.jpg', 10, 11),
	(162, 'Up to 1951 a huge 25 meter high sculpture of Joseph Stalin was standing at the place of the current rocket near the Space pavilion. It was one of the main symbols of VDNKh in 1939.', '023.jpg', 11, 11),
	(163, 'The prototype of the most famous Soviet aircraft TU-154 was used as a museum. Over 40 years it has been standing in front of the former pavilion Aviation and Space, which was visited by several million people. On September 13, 2008 the aircraft was cut into scrap metal.', '022.jpg', 12, 11),
	(164, 'There is an illegally built house on the VVC territory, which belongs to the notorious Russian oligarch Yakov Yakubov. This castle is located between pavilions Fishery and Rabbit-breeding. In November 2014 the court returned the ownership of the castle to VVC.', '025.jpg', 13, 11),
	(165, 'Karymskaya Sopka (the Karymsky Volcano) is a restless volcano in Kamchatka\'s eastern zone. This stratovolcano is 1536 meters high (5039 feet), and its crater emits hot gases all the time. Karymskaya Sopka lies in a 5-kilometers (16,404 feet) wide caldera that was formed during the early Holocene period.', '001.jpg', 1, 13),
	(166, 'The volcano has had more than 20 eruptions since 1852. Not far from the Sopka there is a Karymsky Lake which occupies the crater of the long-dormant Akademia Nauk volcano. As a result of a powerful explosion, the lake became dead.', '002.jpg', 2, 13),
	(167, 'During the last 10 years the volcano had 2 eruptions: in 2005 and in 2010.', '003.jpg', 3, 13),
	(168, '', '004.jpg', 4, 13),
	(169, '', '005.jpg', 5, 13),
	(170, '', '006.jpg', 6, 13),
	(171, 'Maly Semyachik is a restless stratovolcano with a short 3,000 meters (9,843 feet) long ridge of three cones. In 1994, a helicopter bumped into one of the cones. Fortunately no one was injured. Its crater is a 700 meters (2,297 feet) deep. Its last eruption took place in 1952.', '007.jpg', 7, 13),
	(172, 'The volcano has a beautiful light-green acidic crater lake. The lake is 500 meters (1,640 feet) in diameter, its depth is 140 meters (459 feet) and temperature is 30-40 °C (86- 104 °F), and it never freezes. A 20 meter bluff rock leads to the lake.', '008.jpg', 8, 13),
	(173, '', '009.jpg', 9, 13),
	(174, '', '010.jpg', 10, 13),
	(175, '', '011.jpg', 11, 13),
	(176, 'Kronotskaya Sopka is an active volcano 3528 meters (11,574 feet) high. The volcano has a beautiful particularly symmetrical cone shape. Its crater is filled with a plug of a volcanic neck. It consists of lava and ash, specially basaltic dross. It emits very rarely.', '012.jpg', 12, 13),
	(177, 'The Kronotsky volcano is not only perfectly shaped, but also it is one of the most beautiful in the world. Its lower slopes are covered with cedar woodlands, and its upper slopes are covered with glaciers and snow patches.', '013.jpg', 13, 13),
	(178, 'Kronotskoye Lake is the largest freshwater lake in Kamchatka. Its area is 242 square kilometers and it has a shape of a triangle. Its maximum depth is 48 meters (157 feet). It was formed 10,000 years ago as a result of a massive lava flow caused by eruptions of the Kronotsky and Krasheninnikov volcanos.', '014.jpg', 14, 13),
	(179, 'The lake alimentation is mixed snow and rain, and it has 11 islands at its eastern shore rising 25 to 30 meters above the surface. 10 rivers flow into the lake, such as the Listvennaya, Uzon, Severnaya, etc. Two species of fish, red salmon and loach, populate the lake.', '015.jpg', 15, 13),
	(180, '', '016.jpg', 16, 13),
	(181, '', '017.jpg', 17, 13),
	(182, '', '018.jpg', 18, 13),
	(183, 'Kizimen volcano (Schapinskaya Sopka) is a restless stratovolcano 2376 meters (7,795 feet) high. The volcano is located in Shchapina graben, on the SE margin of the Central Kamchatkan Valley. It is 265 kilometers (164 miles) far from Petropavlovsk-Kamchatsly city.', '019.jpg', 19, 13),
	(184, 'The stratovolcano is 12,000 years old. It was formed by lava domes and has a cone shape. Its slopes are covered with the volcanic blowouts, small glaciers and snow patches. Its latest eruption took place in 2009-2010.', '020.jpg', 20, 13),
	(185, '', '021.jpg', 21, 13),
	(186, '', '022.jpg', 22, 13),
	(187, '', '023.jpg', 23, 13),
	(188, '', '024.jpg', 24, 13),
	(189, 'The beautiful hot springs are located next to the volcano. Touristic routes in the area lead to the Tumrock thermal springs.', '025.jpg', 25, 13),
	(190, '', '026.jpg', 26, 13),
	(191, '', '027.jpg', 27, 13),
	(192, '', '028.jpg', 28, 13),
	(193, '', '029.jpg', 29, 13),
	(194, 'The Kluchevskaya group of volcanoes is the largest in Russia. It belongs to the western volcanic belt. The hill on the next two pictures in the area of the Tolbachinsky Dol was formed for the reason of the volcanic activity under the earth surface.', '030.jpg', 30, 13),
	(195, 'Tolbachik is a volcano in the SW of the Kluchevskaya group of volcanoes. It is 3682 meters (12,080 feet) high and includes two volcanoes: the Ostry Tolbachik and Plosky Tolbachik with more than 120 slag cones on its slopes.', '031.jpg', 31, 13),
	(196, 'Ostry Tolbachik is a dormant stratovolcano with a destroyed peak. The Plosky Tolbachik is a stratovolcano with a respectively a flat-top and two craters. The biggest one is 3 kilometers (1.86 miles) in diameter and filled with dejectas and a glacier.', '032.jpg', 32, 13),
	(197, '', '033.jpg', 33, 13),
	(198, 'The Kluchevskaya Sopka and the Kamen Volcanoes', '034.jpg', 34, 13),
	(199, 'Kamen is a dormant volcano located next to the Kluchevskaya Sopka. It is the second highest volcano in Kamchatka and belongs to the Eastern volcanic belt. Kamen used to have a beautifule cone shape, but it was destroyed with powerful explosions. The volcano is 4579 meters (15,022 feet) high and it erupted for the last time in 808 B. C. To reach its top climbers use its western slope.', '035.jpg', 35, 13),
	(200, 'Kluchevskaya Sopka is an active stratovolcano 4850 meters (15,912 feet) high. It is the highest active restless volcano in Eurasia. The volcano is 7,000 years old.', '036.jpg', 36, 13),
	(201, 'It is located 60 kilometers (37 miles) far from the Kamchatsly Gulf of the Pacific Ocean. The volcano has steep, symmetrical cone towers on its slopes. Despite the fact that the volcano is high, there is no snow and ice on its top. After the last eruption in 2009 the volcano\'s height raised up to 5000 meters (16,404 feet). The saddle between the Kluchevsky and Kamen volcanoes.', '037.jpg', 37, 13),
	(202, '', '038.jpg', 38, 13),
	(203, '', '039.jpg', 39, 13),
	(204, 'The volcano which eruption has started in 2009 is the most active nowadays.', '040.jpg', 40, 13),
	(205, '', '041.jpg', 41, 13),
	(206, 'The Bolshaya and Malaya Udina Volcanoes. Bolshaya Udina is a two-level stratovolcano located in the Kluchevskaya Volcanic Group. It has a cone shape and its height is 2923 meters (9590 feet). The volcano in dormant now, and the date of its latest eruption is unknown. Malaya Udina is a dormant stratovolcano located not far from the Bolshaya Udina. It has a sharp symmetrical cone shape and its height is 1945 meters (6,381 feet).', '042.jpg', 42, 13),
